def host_name(host):
    return host if host is not None else 'Local'


class ta5g_egate(object):
    def __init__(self):
        self._ute_wtssim_instance = BuiltIn().get_library_instance('ute_wtssim')
        self.ta5g_cell_operations = ta5g_cell_operations()
        self._egate_console_log_path = "/opt/iphy/latest/egate_console.log"

    def set_egate_console_log_path(self, path):
        self._egate_console_log_path = path

    def set_debug_log_level_from_epc_sim(self, log_level=0):
        logger.console("Set Debug Log Level From Epc Sim log_level={}".format(log_level))
        self._ute_wtssim_instance.execute_egate_command('debug_log level={}'.format(log_level))

    def set_action_for_ue_with_given_rrc_connection_reconfiguration(
            self, rrc_reconf_field, ue_id, action, occurence_number=1, delay=0
    ):
        logger.console(
            "Setting {} action with delay {} for {}. occurrence of RRC msg containing {} for Ue {}".format(
                action, delay, occurence_number, rrc_reconf_field, ue_id
            )
        )
        self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_param id={} if_rrc_reconf_contains={} nth={} action={} delay={}'.format(
                ue_id, rrc_reconf_field, occurence_number, action, delay
            )
        )

    def execute_egate_cmd_and_wait_for_data(self, cmd, timeout=None, pass_regexp=None, fail_regexp=None, return_output=True):
        """
        Method used for executing command on egate and wait for data from the command.

        :param cmd: Egate command to execute.
        :param timeout: by default 10 seconds. Can be specified in human format like 5s, 10minutes, 1min 5s.
        :param pass_regexp: Regexp indicating that the command passed.
        :param fail_regexp: Regexp indicating that the command failed.
        """
        return self._ute_wtssim_instance.execute_egate_command_and_wait_for_data(cmd=cmd, timeout=timeout, pass_regexp=pass_regexp,
                                                                                 fail_regexp=fail_regexp, return_output=return_output)

    def execute_egate_cmd(self, cmd, pass_regexp=None, fail_regexp=None, timeout=None, return_output=True):
        """
        Method used for executing command on egate.

        :param cmd: Egate command to execute.
        :param pass_regexp: Regexp indicating that the command passed.
        :param fail_regexp: Regexp indicating that the command failed.
        :param timeout: by default 10 seconds. Can be specified in human format like 5s, 10minutes, 1min 5s.

        """
        return self._ute_wtssim_instance.execute_egate_command(cmd=cmd, pass_regexp=pass_regexp, fail_regexp=fail_regexp, timeout=timeout,
                                                               return_output=return_output)

    def wait_for_egate_console_output(self, expected_message, timeout, unexpected_message=None):
        """
        Execute command sim_state_disp in egate for expecting message
        :param expected_message: message in a egate-like format
        :param timeout:
        :param unexpected_message: keyword will fail if it appears
        :return:
        """
        logger.console("Waiting for {} info in egate console".format(expected_message))
        self._ute_wtssim_instance.execute_egate_command(
            cmd='sim_state_disp',
            pass_regexp=expected_message,
            fail_regexp=unexpected_message,
            timeout=timeout,
        )

    def verify_egate_content(self, expected_pattern='', occurrence=1):
        """
        Check in egate_console.log if expected pattern occurred exactly equal or more times
        :param expected_pattern: regexp to match in /opt/iphy/latest/egate_console.log with 'grep -P' command
        :param occurrence: expected number of prints
        :return: Error if expected number of prints is not found (is less than given occurrence)
        """
        self.clear_egate_buffer_from_logs()
        time.sleep(4)
        count_occurrences_cmd = "grep -P \"{}\" /opt/iphy/latest/egate_console.log | wc -l".format(expected_pattern)
        result = subprocess.check_output(count_occurrences_cmd, shell=True)
        if int(result) >= occurrence:
            return
        else:
            raise AssertionError(
                "Could not find expected pattern: '{}' {} or more times.".format(expected_pattern, occurrence))

    def check_if_crash_is_visibe_in_egate(self, expected_pattern_list=['Crash', 'Segmentation fault']):
        """
        Check in egate_console.log if expected_pattern occured
        :expected_pattern_list: list of serached patterns, by default: ['Crash', 'Segmentation fault']
        """
        self.clear_egate_buffer_from_logs()
        time.sleep(4)
        for pattern in expected_pattern_list:
            count_occurrences_cmd = "grep -iP \"{}\" /opt/iphy/latest/egate_console.log | wc -l".format(pattern)
            result = subprocess.check_output(count_occurrences_cmd, shell=True)
            if int(result) >= 1:
                logger.console("WARNING")
                logger.console("IN egate_console.log THERE IS {} LOGGED, CHECK IF IT'S NOT A CASE FOR PRONTO".format(pattern))
                break

    def send_mme_pool_configuration_update(self, mme_id, pools):
        """
        Send MME Pool Configuration Update    mme_id=1    pools= pool=2:1 pool=3:1
        MME pool areas are configured in LUA configuration file e.g.
        mme_pool_area id=1 mmegi=1 plmn=244:09 tac_list=124
        MME Pool Area: pool=id:mmec    id - id of mme_pool_area from LUE file,    mmec - value of MME Code
        :param mme_id:
        :param pools: string injected directly into egate command and has to follow egate syntax. Example of use:
        :return:
        """
        logger.console("Send MME Pool Configuration Update mme_id={} pools= {}".format(mme_id, pools))
        self._ute_wtssim_instance.execute_egate_command('mme_config_update id={} {}'.format(mme_id, pools))

    def set_nrarfcn(self, downlink_nrarfcn_value, uplink_nrarfcn_value, cell_number, lua_path):
        """
        Common method to change nrarfcn for TDD & FDD in lua file
        :param downlink_nrarfcn_value: value of dl nrarfcn
        :param uplink_nrarfcn_value: value of ul nrarfcn
        :param cell_number: number of
        :param lua_path: path to lua file
        :return:
        """
        with open(lua_path, 'r', encoding='utf-8') as file:
            data = file.readlines()
        for line_idx in range(len(data)):
            if "set_cell id={}".format(cell_number) in data[line_idx] and 'nr_arfcn' in data[line_idx]:
                new_line = re.sub(r'nr_arfcn=\d+:\d+\s', 'nr_arfcn={}:{} '.
                                  format(uplink_nrarfcn_value, downlink_nrarfcn_value, ), data[line_idx])
                data[line_idx] = new_line
                break
        with open(lua_path, 'w', encoding='utf-8') as file:
            file.writelines(data)

    def align_lua_nrarfcn_to_scf(self, lua_path):
        """
        Get value from gNB about nrarfcn and cell technology (TDD, FDD). Update values in .lua file
        :param lua_path: path to .lua file
        :return:
        """
        nrarfcn_dl_list, nrarfcn_ul_list, cell_technology_list = self.ta5g_cell_operations._get_cells_with_nrarfcn()
        change_airphone_xml = True if len(cell_technology_list) == 1 else False
        for cell_id, cell_technology in enumerate(cell_technology_list):
            if cell_technology == 'FDD':
                self.align_lua_files_to_fdd(lua_path, cell_id + 1, nrarfcn_dl_list[cell_id], nrarfcn_ul_list[cell_id],
                                            change_airphone_xml_path=change_airphone_xml)
            else:
                self.align_lua_files_to_tdd(lua_path, cell_id + 1, nrarfcn_dl_list[cell_id], nrarfcn_ul_list[cell_id])

    def align_lua_files_to_tdd(self, lua_path, cell_id, nrarfcn_dl, nrarfcn_ul):
        self.change_tdd_cell_value_in_lua_according_to_scf(scf_value='on', path_to_lua=lua_path,
                                                           occurence=cell_id)
        self.set_nrarfcn(downlink_nrarfcn_value=nrarfcn_dl,
                         uplink_nrarfcn_value=nrarfcn_ul,
                         cell_number=cell_id, lua_path=lua_path)

    def align_lua_files_to_fdd(self, lua_path, cell_id, nrarfcn_dl, nrarfcn_ul, change_airphone_xml_path=False):
        """
        Nrarfcn in downlink and uplink is changed in .lua file. Path to AirphoneConfig FDD is changed in .lua file
        :param lua_path: path to lua file
        :return:
        """
        if change_airphone_xml_path:  # works only for single cell - hopefully in the future AP.xml will be removed
            self.change_lua_to_scf(lua_variable='AP_CONFIG_PATH',
                                   scf_value=r'\/home\/ute\/Auto5G\/testsuite\/RRM\/5G_SW_WRO\/resources\/'
                                             r'AirPhoneConfig_SA_FDD.xml',
                                   path_to_lua=lua_path)

        self.change_tdd_cell_value_in_lua_according_to_scf(scf_value='off', path_to_lua=lua_path,
                                                           occurence=cell_id)
        self.set_nrarfcn(downlink_nrarfcn_value=nrarfcn_dl,
                         uplink_nrarfcn_value=nrarfcn_ul,
                         cell_number=cell_id, lua_path=lua_path)

    def change_tdd_cell_value_in_lua_according_to_scf(self, scf_value, path_to_lua, occurence=0):
        with open(path_to_lua, 'r', encoding='utf-8') as file:
            data = file.readlines()
        for line_idx in range(len(data)):
            if "set_cell id={}".format(occurence) in data[line_idx] and 'tdd_cell' in data[line_idx]:
                new_line = re.sub(r'tdd_cell=[a-z]+\s', 'tdd_cell={} '.format(scf_value), data[line_idx])
                data[line_idx] = new_line
                break
        with open(path_to_lua, 'w', encoding='utf-8') as file:
            file.writelines(data)

    def align_lua_local_ip_addr_to_scf(self, lua_path):
        """
        Get local_ip_addr values from gNB and update those values in .lua file
        :param lua_path: path to lua file
        :return:
        """
        infomodel_object = sorted(ta5g_admin_operations()._get_managed_objects('IPADDRESSV4_A'),
                                  key=lambda x: x['distName'])

        if len(infomodel_object) == 1:
            first_local_ip_address = str(infomodel_object[0]['parameters']['localIpAddr'])
            if ta5g_cell_operations().check_if_nsa_cell(1):
                self.change_lua_to_scf(lua_variable='GNB_X2_ADDR', scf_value=first_local_ip_address,
                                       path_to_lua=lua_path)
                self.change_lua_to_scf(lua_variable='GNB_S1U_ADDR', scf_value=first_local_ip_address,
                                       path_to_lua=lua_path)
            else:
                self.change_lua_to_scf(lua_variable='GNB_NG_ADDR', scf_value=first_local_ip_address,
                                       path_to_lua=lua_path)
        elif len(infomodel_object) == 2:
            first_local_ip_address = str(infomodel_object[0]['parameters']['localIpAddr'])
            second_local_ip_address = str(infomodel_object[1]['parameters']['localIpAddr'])
            self.change_lua_to_scf(lua_variable='GNB_X2_ADDR', scf_value=first_local_ip_address, path_to_lua=lua_path)
            self.change_lua_to_scf(lua_variable='GNB_S1U_ADDR', scf_value=second_local_ip_address, path_to_lua=lua_path)
        else:
            logger.warn(msg='Local ip address param at gnb is configured more than 1 or 2 times, please check it')

    @staticmethod
    def change_lua_to_scf(lua_variable, scf_value, path_to_lua, quotes=True, occurence=0):
        """
        Common method to update .lua file according to values in gNB scf
        :param lua_variable: lua_variable
        :param scf_value: scf_value
        :param path_to_lua: path to lua file
        :param quotes: if True then method adds quotation marks around new value, else quotation marks are not added
        :param occurence: tells which occurence should be replaced (first second etc.), default 0 which means all.
        :return:
        """
        if occurence == 0:
            occurence = 'g'
        quote = "\\\"" if quotes else ""
        system(
            "sed -E -z \"s/{}=[^\'\\)|^[:space:]]+/{}={}{}{}/\"{} -i {}".format(
                lua_variable, lua_variable, quote, scf_value, quote, occurence, path_to_lua)
        )

    def set_tac(self, cell_pci, tac_value, original_file):
        system(
            'sed -E -z \"s/pci={} tac=[0-9]*/pci={} tac={}/g\" -i {}'.format(
                cell_pci,
                cell_pci,
                tac_value,
                original_file
            )
        )

    def set_tac_list(self, tac_value, original_file):
        system(
            'sed -E -z \"s/set_amf_region id=1 tac_list=/set_amf_region id=1 tac_list={},/g\" -i {}'.format(
                tac_value,
                original_file
            )
        )

    def _tacs_and_cells_dict_prep(self, tac_dictionary, cells_dictionary, cells_affiliation_dictionary):
        tacs_and_cells_dict = {}
        for x in cells_dictionary.keys():
            for y in cells_affiliation_dictionary.keys():
                if re.search(x, y):
                    tacs_and_cells_dict[cells_dictionary.get(x)] = tac_dictionary.get(
                        cells_affiliation_dictionary.get(y))
        return tacs_and_cells_dict

    def align_lua_tac_to_scf(self, lua_path):  # noqa: C901
        tac_dictionary = ta5g_admin_operations().get_parameter_values_for_objects(
            object_types=['TRACKINGAREA', 'ADJ_NRPLMNSET_SA', 'NRADJNRCELL'],
            mocs=['TRACKINGAREA_A', 'ADJ_NRPLMNSET_SA_A', 'NRADJNRCELL_A'],
            parameter='fiveGsTac')
        cells_dictionary = ta5g_admin_operations().get_parameter_values_for_objects(
            object_types=['NRCELL', 'ADJ_NRPLMNSET_SA', 'NRADJNRCELL'],
            mocs=['NRCELL_A', 'ADJ_NRPLMNSET_SA_A', 'NRADJNRCELL_A'],
            parameter='physCellId')
        cells_affiliation_dictionary = ta5g_admin_operations().get_parameter_values_for_objects(
            object_types=['ADJ_NRPLMNSET_SA', 'NRADJNRCELL', 'NRCELL'],
            mocs=['NRPLMNSET_SA_A', 'ADJ_NRPLMNSET_SA_A', 'NRADJNRCELL_A'],
            parameter='trackingAreaDN')

        tacs_and_cells_dict = self._tacs_and_cells_dict_prep(tac_dictionary, cells_dictionary, cells_affiliation_dictionary)

        pci_and_tacs_dict = {}
        for key in list(tacs_and_cells_dict.keys()):
            pci_part_1 = key // 3
            pci_part_2 = key % 3
            key_as_pci = str(pci_part_1) + ":" + str(pci_part_2)
            pci_and_tacs_dict[key_as_pci] = tacs_and_cells_dict.get(key)
        for pci in list(pci_and_tacs_dict.keys()):
            self.set_tac(
                cell_pci=pci,
                tac_value=pci_and_tacs_dict[pci],
                original_file=lua_path
            )
        for tac in list(set(pci_and_tacs_dict.values())):
            with open(lua_path, 'r') as lua_file:
                lua_file_read = lua_file.read()
                found_matches = re.findall(r'exec\(\'set_amf_region id=1 tac_list=[0-9,]*', lua_file_read)
                found_tac_matches = found_matches[0].replace(" ", ",")
                found_tac_matches = re.split(",|=", found_tac_matches)
                if str(tac) not in found_tac_matches:
                    self.set_tac_list(tac_value=tac, original_file=lua_path)
                lua_file.close()

    @log_name(level="INFO")  # noqa: C901
    def start_wts_and_store_config_file_in_logs_dir(self, lua_cfg, logs_dirpath=None, check_edaemon_port=False,  # noqa: C901
                                                    align_tac_values=True):
        """
        Start WTS application and configure using .lua config file
        :param lua_cfg: File path of .lua config file
        :param check_edaemon_port: Default False, if True then function will search for port in lua_cfg
        :return:
        """
        if not logs_dirpath:
            logs_dirpath = ta5g_interface_tools().get_robot_output_dir()
        lua_paths, ext_libs = generate_lua_paths()
        logger.info(lua_paths)
        if '.lua' in lua_cfg:
            new_lua_cfg_name = 'updated_egate.lua'
            line_to_add = "\"exec('set_log log_to_file=on')\""
        else:
            new_lua_cfg_name = 'updated_egate.cfg'
            line_to_add = "'set_log log_to_file=on'"
        new_lua_cfg = path.join(logs_dirpath, new_lua_cfg_name)
        system("echo {} > {}; cat {} >> {}".format(line_to_add, new_lua_cfg, lua_cfg, new_lua_cfg))
        self.align_lua_nrarfcn_to_scf(lua_path=new_lua_cfg)
        self.align_lua_local_ip_addr_to_scf(lua_path=new_lua_cfg)
        self._try_to_align_tac_values(align_tac_values, new_lua_cfg)
        if check_edaemon_port:
            self._start_wts_apps_with_edaemon(ext_libs, lua_cfg, lua_paths, new_lua_cfg)
        else:
            self._ute_wtssim_instance.start_wts_applications(
                cfg_file=new_lua_cfg, timeout=120, lua_dirs=lua_paths, ext=ext_libs
            )
        wts_log_path = path.join(logs_dirpath, 'wts/')
        if not path.exists(wts_log_path):
            mkdir(wts_log_path)
        copyfile(lua_cfg, '{}{}'.format(wts_log_path, lua_cfg.split('/')[-1]))

    def _try_to_align_tac_values(self, align_tac_values, new_lua_cfg):
        if align_tac_values:
            try:
                self.align_lua_tac_to_scf(lua_path=new_lua_cfg)
            except Exception:
                logger.info("TAC values not found correctly in scf, .lua/.cfg file TAC values will not be aligned",
                            also_console=True)

    def _start_wts_apps_with_edaemon(self, ext_libs, lua_cfg, lua_paths, new_lua_cfg):
        with open(lua_cfg, "r") as fd_lua_cfg:
            content_of_lua_cfg_file = fd_lua_cfg.read()
        port_from_lua_cfg = re.search('(?<=DAEMON_PORT=(\"|\')).*(?=(\"|\'))', content_of_lua_cfg_file).group()
        self._ute_wtssim_instance.start_wts_applications(edaemon_ports=port_from_lua_cfg, cfg_file=new_lua_cfg,
                                                         timeout=120, lua_dirs=lua_paths, ext=ext_libs)

    def is_sib1_transmitted_for_given_cell(self, cell_id, cell_info, remote_host=None):
        if self.ta5g_cell_operations.check_if_sa_cell(cell_id, remote_host) or self.ta5g_cell_operations.check_if_sansa_cell(
                cell_id, remote_host):
            return True
        elif self.ta5g_cell_operations.check_if_nrdcsn_cell(cell_id, remote_host):
            return False
        else:
            return cell_info['parameters']['actSib1ForNsaCell']

    def check_if_sib1_will_be_transmitted_for_5g_cells(self, cells, remote_host=None):
        sib1_for_gnb = {}
        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            cells_list = sorted(admin_client.get_managed_objects('NRCELL_A'), key=lambda x: x['distName'])
        for cell_idx in range(len(cells)):
            sib1_for_gnb[cells[cell_idx]] = self.is_sib1_transmitted_for_given_cell(cells[cell_idx], cells_list[cell_idx])
        return sib1_for_gnb

    @log_name(level="INFO")
    def reach_onair(self, lua_cfg, logs_dirpath=None, timeout=180, check_edaemon_port=False, align_tac_values=True,
                    x2_setup_pass_regexp=".*", cell_type=None, remote_hosts=None, mplane_cells=None, multi_ap=None,
                    keep_alive=False):
        if ta5g_admin_operations().is_classical() and cell_type:
            self.reach_onair_classical_and_lock_cells(lua_cfg, cell_type, logs_dirpath, timeout, check_edaemon_port,
                                                      align_tac_values, x2_setup_pass_regexp)
        elif ta5g_admin_operations().is_classical():
            self.reach_onair_classical(lua_cfg, logs_dirpath, timeout, check_edaemon_port, align_tac_values,
                                       x2_setup_pass_regexp, remote_hosts=remote_hosts, mplane_cells=mplane_cells,
                                       multi_ap=multi_ap, keep_alive=keep_alive)
        else:
            self.reach_onair_aic(lua_cfg, logs_dirpath, timeout, check_edaemon_port, align_tac_values,
                                 x2_setup_pass_regexp)

    @log_name(level="INFO")
    def reach_onair_classical(self, lua_cfg, logs_dirpath=None, timeout=180, check_edaemon_port=False,
                              align_tac_values=True, x2_setup_pass_regexp=".*", remote_hosts=None, mplane_cells=None,
                              multi_ap=None, keep_alive=False):
        """
        Start simulated ethernet interfaces. Then align .lua/.cfg file to actual configuration and ta5g libs needs
        (smooth TDD <-> FDD switching, alignment of nrarfcn and TAC values - if chosen). Using aligned lua_cfg file, run
        WTS application and start Core simulation. Wait until cells reach 'on air'. As a last step, try to setup X2AP interface
        with an option to check the result.
        :param lua_cfg: File path of .lua config file
        :param logs_dirpath: Directory for output logs
        :param timeout: Timeout for cells enabling, MIB and SIB1 reception
        :param check_edaemon_port: Default False, if True then function will search for port in lua_cfg
        :param align_tac_values: Default True, the function will align TAC values in .lua/.cfg file to scf
        :param x2_setup_pass_regexp: Default ".*", the function will set x2_setup_pass_regexp
        :multi_ap: list of additional AP Ips where radios availability should be checked, by default None
        :keep_alive: bool, when set to True disables log collection and doesn't teardown egate
        :return:
        """
        collect_l1l2 = BuiltIn().get_variable_value('${COLLECT_L1L2_LOGS}')
        if collect_l1l2:
            L1L2Collector().setup_and_start_collector()

        self._ute_wtssim_instance.save_egate = keep_alive or BuiltIn().get_variable_value('${KEEP_ALIVE}')

        if not logs_dirpath:
            logs_dirpath = ta5g_interface_tools().get_robot_output_dir()

        ta5g_testline_management.ta5g_testline_management.start_default_simulated_SANSA_interfaces()
        self.start_wts_and_store_config_file_in_logs_dir(lua_cfg=lua_cfg, logs_dirpath=logs_dirpath,
                                                         check_edaemon_port=check_edaemon_port,
                                                         align_tac_values=align_tac_values)
        if multi_ap:
            ta5g_iphy.ta5g_iphy().check_radios_availability_multi_ap(iphy_lmp_ips=multi_ap)
        else:
            ta5g_iphy.ta5g_iphy().check_radios_availability(remote_hosts=remote_hosts)
        self._ute_wtssim_instance.execute_egate_command(cmd='start version_check=off', timeout=10)

        remote_hosts = [None] if remote_hosts is None else [None] + remote_hosts

        for remote_host in remote_hosts:
            logger.info('*** Waiting for {} host\'s cells to be active ***'.format(host_name(remote_host)), also_console=True)
            self.ta5g_cell_operations.wait_for_all_cells_to_be_enabled(timeout=timeout, remote_host=remote_host)
            if not mplane_cells:
                self.wait_for_mib_reception(timeout=timeout, remote_host=remote_host)
                self.wait_for_sib1_reception(timeout=timeout, remote_host=remote_host)
            else:
                mplane_cells_list = [int(cell) for cell in mplane_cells]
                list_of_all_cells_ids = sorted(ta5g_cell_operations().get_list_of_all_cells_ids())
                list_of_cells_to_check = [cell for cell in list_of_all_cells_ids if cell not in mplane_cells_list]
                self.wait_for_mib_reception(cell_list=list_of_cells_to_check, timeout=timeout, remote_host=remote_host)
                self.wait_for_sib1_reception(cell_list=list_of_cells_to_check, timeout=timeout, remote_host=remote_host)
            logger.info('*** All {} host\'s cells are active ***'.format(host_name(remote_host)), also_console=True)

        self._ute_wtssim_instance.execute_egate_command(cmd="enb_x2_link_up enb=1 target=2",
                                                        pass_regexp=x2_setup_pass_regexp,
                                                        timeout=5)

    @log_name(level="INFO")  # noqa: C901
    def reach_onair_classical_and_lock_cells(self, lua_cfg, cell_type, logs_dirpath=None, timeout=180,  # noqa: C901
                                             check_edaemon_port=False, align_tac_values=True,
                                             x2_setup_pass_regexp=".*"):
        """
        Start simulated ethernet interfaces. Lock selected cells, then align .lua/.cfg file to actual configuration and ta5g libs needs
        (smooth TDD <-> FDD switching, alignment of nrarfcn and TAC values - if chosen). Using aligned lua_cfg file, run
        WTS application and start Core simulation. Wait until selected type of cells reach 'on air'.
        As a last step, try to setup X2AP interface with an option to check the result.
        :param lua_cfg: File path of .lua config file
        :param cell_type: Cell type to be enabled (TDD/FDD)
        :param logs_dirpath: Directory for output logs
        :param timeout: Timeout for cells enabling, MIB and SIB1 reception
        :param check_edaemon_port: Default False, if True then function will search for port in lua_cfg
        :param align_tac_values: Default True, the function will align TAC values in .lua/.cfg file to scf
        :param x2_setup_pass_regexp: Default ".*", the function will set x2_setup_pass_regexp
        :return:
        """
        available_cell_types = ['tdd', 'fdd']
        if cell_type.lower() not in available_cell_types:
            raise Exception("Provided Cell Type must be either FDD or TDD.")

        collect_l1l2 = BuiltIn().get_variable_value('${COLLECT_L1L2_LOGS}')
        if collect_l1l2:
            L1L2Collector().setup_and_start_collector()

        if not logs_dirpath:
            logs_dirpath = ta5g_interface_tools().get_robot_output_dir()

        cells_dict = self.ta5g_cell_operations.get_dict_of_cells_with_type()

        available_cell_types.remove(cell_type.lower())
        try:
            for i in cells_dict[available_cell_types[0]]:
                self.ta5g_cell_operations.lock_single_cell(cell_id=i)
        except Exception:
            logger.info("Unable to lock cells of type {}".format(available_cell_types[0]))

        ta5g_testline_management.ta5g_testline_management.start_default_simulated_SANSA_interfaces()
        self.start_wts_and_store_config_file_in_logs_dir(lua_cfg=lua_cfg, logs_dirpath=logs_dirpath,
                                                         check_edaemon_port=check_edaemon_port,
                                                         align_tac_values=align_tac_values)
        ta5g_iphy.ta5g_iphy().check_radios_availability()
        self._ute_wtssim_instance.execute_egate_command(cmd='start version_check=off', timeout=10)

        self.ta5g_cell_operations.wait_for_selected_cells_to_be_enabled(timeout=timeout,
                                                                        cell_list=cells_dict[cell_type.lower()])
        self.wait_for_mib_reception(cell_list=cells_dict[cell_type.lower()], timeout=timeout)
        self.wait_for_sib1_reception(cell_list=cells_dict[cell_type.lower()], timeout=timeout)

        self._ute_wtssim_instance.execute_egate_command(cmd="enb_x2_link_up enb=1 target=2",
                                                        pass_regexp=x2_setup_pass_regexp,
                                                        timeout=5)

    def reach_onair_and_wait_for_setup(self, lua_cfg, logs_dirpath=None, timeout=180, check_edaemon_port=False,
                                       x2_setup_pass_regexp=r"ENB-[0-9]+: X2AP Link with GNB-[0-9]* \S* is up",
                                       align_tac_values=True):
        """
        Start simulated ethernet interfaces. Then align .lua/.cfg file to actual configuration and ta5g libs needs
        (smooth TDD <-> FDD switching, alignment of nrarfcn and TAC values - if chosen). Using aligned lua_cfg file, run
        WTS application and start Core simulation. Wait until cells reach 'on air'. As a last step, setup X2AP interface
        expecting the x2_pass_regexp in Egate output. Duble check of x2_pass_regexp is conducted in the last step of this method
        """
        self.reach_onair(lua_cfg, logs_dirpath=logs_dirpath, timeout=timeout, check_edaemon_port=check_edaemon_port,
                         align_tac_values=align_tac_values, x2_setup_pass_regexp=x2_setup_pass_regexp)

