    def get_ue_crnti(self, ue_id, pass_regexp='.*C-RNTI.*'):
        cmd_output = self._ute_wtssim_instance.execute_egate_command(
            cmd='ue_disp id={}'.format(ue_id), pass_regexp=pass_regexp
        )
        _, crnti = BuiltIn().should_match_regexp(cmd_output, r'.*C-RNTI\s+(\d+).*')
        return crnti

    def create_egatescript_for_cell_checking(self, filepath):
        with open(filepath, "w") as f:
            f.write("""
                    function is_cell_onair(enb_id, cell_id)
                    cell_info = enb(enb_id):cell(cell_id).info
                    print("ENB "..enb_id.." CELL "..cell_id..": "..tostring(cell_info.is_connected and not cell_info.is_blocked))
                    end
                    """)

    def _check_if_cell_is_onair(self, enb_id, cell_id):
        lua_script_path = path.join(path.dirname(__file__), 'egate_scripts.lua')
        if not exists(lua_script_path):
            self.create_egatescript_for_cell_checking(lua_script_path)
        cmd = 'script file=%s entry=is_cell_onair(%d,%d)\n' % (lua_script_path, int(enb_id), int(cell_id))
        regexp = re.compile(r'ENB %d CELL %d: (\w+)' % (int(enb_id), int(cell_id)), re.DOTALL)
        result = self._ute_wtssim_instance.execute_egate_command(cmd=cmd, pass_regexp=regexp)
        search_result = regexp.search(re.sub(r'\x1b..', '', result))
        if search_result is None:
            raise AssertionError("Couldn't determine the cell status!")
        return ('true' in search_result.group(1) and 'false' not in search_result.group(1))

    def check_if_cell_is_onair(self, enb_id, cell_id):
        """
        Check if cell is onair from egate perspective
        :param enb_id:
        :param cell_id:
        :return:
        """
        if not self._check_if_cell_is_onair(enb_id, cell_id):
            raise AssertionError("ENB %d CELL %d is not onair from egate perspective" % (int(enb_id), int(cell_id)))

    def check_if_all_cells_are_onair(self, enb_id=2):
        """
        Check if all cells are onair from egate perspective
        :param enb_id: specified in egate configuration file, by default 2
        :return:
        """
        list_of_cells_ids = sorted(ta5g_cell_operations().get_list_of_all_cells_ids())
        for cell in list_of_cells_ids:
            self.check_if_cell_is_onair(enb_id, cell)

    def check_if_cells_are_onair(self, cell_id_list, enb_id=2):
        """
        Check if cells specified in cell_id_list parameter are onair from egate perspective
        :param cell_id_list: cell ids specified in egate configuration file
        :param enb_id: specified in egate configuration file, by default 2
        :return:
        """
        for cell in cell_id_list:
            self.check_if_cell_is_onair(enb_id, cell)

    def wait_until_cells_are_onair(self, timeout, enb_id, cell_ids):
        """
        :param timeout:
        :param enb_id: specified in egate configuration file
        :param cell_ids: int or list with ids specified in egate configuration file
        :return:
        """
        if not isinstance(cell_ids, list):
            cell_ids = [cell_ids]
        start = time.time()
        while time.time() - start < float(timeout):
            if all(self._check_if_cell_is_onair(enb_id, cell_id) for cell_id in cell_ids):
                return
            time.sleep(0.5)
        raise AssertionError("Not all cells were OnAir from egate perspective after {} seconds".format(timeout))

    @staticmethod
    def determine_details_of_mib():
        list_of_cells_ids = sorted(ta5g_cell_operations().get_list_of_all_cells_ids())
        mib_cells_dict = {2: [i for i in list_of_cells_ids]}  # noqa: C416
        return mib_cells_dict

    def determine_details_of_sibs1_to_check(self):
        list_of_cells_ids = sorted(self.ta5g_cell_operations.get_list_of_all_cells_ids())
        sib1_for_gnb = self.check_if_sib1_will_be_transmitted_for_5g_cells(list_of_cells_ids)
        cells_dict = {2: [i for i in list_of_cells_ids if sib1_for_gnb[i]]}
        return cells_dict

    @log_name(level="INFO")
    def wait_for_mib_reception(self, timeout=180, cell_list=None, remote_host=None):
        if cell_list:
            mib_cells_dict = {2: [i for i in cell_list]}  # noqa: C416
        elif remote_host is not None:
            expected_freqs = self._get_frequencies_for_cells_expecting_mib(remote_host)
            mib_cells_dict = OnlyExpectedFreqsIDMapper(self._egate_console_log_path, expected_freqs).prepare_mapping()
        else:
            mib_cells_dict = self.determine_details_of_mib()
        self.wait_for_information_block_reception_for_given_cells(
            cells=mib_cells_dict, infoblocktype='MasterInformationBlock', timeout=timeout)

    @log_name(level="INFO")
    def wait_for_sib1_reception(self, timeout=60, cell_list=None, remote_host=None):
        if cell_list:
            cells_dict = {2: [i for i in cell_list]}  # noqa: C416
        elif remote_host is not None:
            expected_freqs = self._get_frequencies_for_cells_expecting_sib1(remote_host)
            cells_dict = OnlyExpectedFreqsIDMapper(self._egate_console_log_path, expected_freqs).prepare_mapping()
        else:
            cells_dict = self.determine_details_of_sibs1_to_check()
        if cells_dict == {}:
            logger.info("NSA configuration, SIB1 turned off on gNB, omitting wait for sib reception", also_console=True)
            return True
        self.wait_for_information_block_reception_for_given_cells(
            cells=cells_dict, infoblocktype='SystemInformationBlockType1', timeout=timeout)

    def _get_frequencies_for_cells_expecting_mib(self, remote_host):
        freqs = []
        cell_infos = []

        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            cell_infos = admin_client.get_cells_info()

        for cell_info in cell_infos:
            valid_freqs = ['nrarfcn', 'nrarfcnDl']

            for freq in valid_freqs:
                try:
                    freqs.append(int(cell_info[freq]))
                except KeyError:
                    pass
        return freqs

    def _get_frequencies_for_cells_expecting_sib1(self, remote_host):
        freqs = []
        cell_infos = []

        with ta_admin_interface.get_admin_interface(remote_host=remote_host) as admin_client:
            cell_infos = admin_client.get_cells_info()

        for cell_info in cell_infos:
            if self.is_sib1_transmitted_for_given_cell(cell_info['globalCellId'], cell_info, remote_host=remote_host):
                valid_freqs = ['nrarfcn', 'nrarfcnDl']

                for freq in valid_freqs:
                    try:
                        freqs.append(int(cell_info[freq]))
                    except KeyError:
                        pass
        return freqs

    def wait_for_information_block_reception_for_given_cells(self, cells, infoblocktype, timeout):
        """
        :param cells:dict: dict with enbs and list of cells for enb eg. cells={1: [1, 2], 2: [1, 2]} means we have
        two cells for eNB1 and two cells for eNB2. Default  one cell for eNB2 {2: [1]}
        :param infoblocktype:
        :param timeout:
        :return:
        """
        if not isinstance(cells, dict):
            raise ValueError("'cells' argument must be dictionary not {}.".format(type(cells).__name__))
        set_of_messages = {"eNB {} cell {}: {}".format(enb_id, cell_id, infoblocktype)
                           for (enb_id, cell_ids) in cells.items() for cell_id in cell_ids}
        regexp = re.compile(r'eNB \d+ cell \d+: {}'.format(infoblocktype))
        logger.info("Waiting for reception of all {} from list: {}".
                    format(infoblocktype, list(set_of_messages)), also_console=True)
        ta5g_admin_operations().check_until_timeout(
            lambda **kwargs: [self.clear_egate_buffer_from_logs(),
                              self._verify_if_all_elements_from_set_are_present_in_file(**kwargs)], timeout,
            check_interval=5, regexp=regexp, set_of_matches=set_of_messages, filename=self._egate_console_log_path)

    @staticmethod
    def _verify_if_all_elements_from_set_are_present_in_file(regexp, set_of_matches,
                                                             filename=r'/opt/iphy/latest/egate_console.log'):
        """
        :param regexp: compiled regexp pattern to search file
        :param set_of_matches: re.findall(regexp, filename) returns all regexp matches and method checks if all
        elements from set_of_matches are present in filename.
        :param filename: path to file in which method should search regexp
        :return:
        """
        with open(filename, "r") as egate_console_log:
            matches = set(re.findall(regexp, egate_console_log.read()))  # if more then one match group this will fail
        if set_of_matches.issubset(matches):
            return True
        else:
            diff = set_of_matches.difference(matches)
            raise ExecutionFailed(message="Values {} are not present in file {}".format(list(diff), filename))

    @staticmethod
    def verify_the_number_of_prints(expected_pattern, filename="/opt/iphy/latest/uec_1.log", occurrence=1):
        """
        Check in given filename if expected pattern occurred given number of times
        :param expected_pattern: pattern of print to search for in given file
        :param filename: path to file in which method should search pattern
        :param occurrence: expected number of prints in given file
        :return: True if expected occurrence is equal to actual number of prints
        """
        with open(filename, "rb") as log_file:
            matches = re.findall(expected_pattern.encode("utf-8"), log_file.read())
            number_of_found_patterns = len(matches)
            if number_of_found_patterns == occurrence:
                logger.info(matches)
                return True
            else:
                raise ValueError("Pattern not found in the file {1} times. {0} != {1}".format(number_of_found_patterns,
                                                                                              occurrence))

