    def start_wts_and_store_config_file_in_logs_dir_aic(self, lua_cfg, logs_dirpath=None, check_edaemon_port=False,
                                                        align_tac_values=True):
        """
        Start WTS application and configure using .lua config file
        :param lua_cfg: File path of .lua config file
        :param check_edaemon_port: Default False, if True then function will search for port in lua_cfg
        :return:
        """
        if not logs_dirpath:
            logs_dirpath = ta5g_interface_tools().get_robot_output_dir()
        lua_paths, ext_libs = generate_lua_paths()
        logger.info(lua_paths)
        if '.lua' in lua_cfg:
            new_lua_cfg_name = 'updated_egate.lua'
            line_to_add = "\"exec('set_log log_to_file=on')\""
        else:
            new_lua_cfg_name = 'updated_egate.cfg'
            line_to_add = "'set_log log_to_file=on'"
        new_lua_cfg = path.join(logs_dirpath, new_lua_cfg_name)
        system("echo {} > {}; cat {} >> {}".format(line_to_add, new_lua_cfg, lua_cfg, new_lua_cfg))
        if check_edaemon_port:
            self._start_wts_apps_with_edaemon(ext_libs, lua_cfg, lua_paths, new_lua_cfg)
        else:
            self._start_wts_apps(ext_libs, lua_paths, new_lua_cfg)
        wts_log_path = path.join(logs_dirpath, 'wts/')
        if not path.exists(wts_log_path):
            mkdir(wts_log_path)
        copyfile(lua_cfg, '{}{}'.format(wts_log_path, lua_cfg.split('/')[-1]))

    def _start_wts_apps(self, ext_libs, lua_paths, new_lua_cfg):
        self._ute_wtssim_instance.start_wts_applications(
            cfg_file=new_lua_cfg, timeout=120, lua_dirs=lua_paths, ext=ext_libs
        )
        logger.info(self._ute_wtssim_instance, also_console=True)

    def is_sib1_transmitted_for_given_cell_aic(self, cell_id):
        if self.ta5g_cell_operations.check_if_sa_cell_aic(cell_id) or self.ta5g_cell_operations.check_if_sansa_cell_aic(
                cell_id):
            return True
        elif self.ta5g_cell_operations.check_if_nrdcsn_cell_aic(cell_id):
            return False
        else:
            return self.ta5g_cell_operations.check_cell_parameter_value_aic(global_cell_id=cell_id,
                                                                            parameter='actSib1ForNsaCell')

    def check_if_sib1_will_be_transmitted_for_5g_cells_aic(self, cells):
        sib1_for_gnb = {}
        for cell_id in range(1, cells + 1):
            sib1_for_gnb[cell_id] = self.is_sib1_transmitted_for_given_cell_aic(cell_id)
        return sib1_for_gnb

    @log_name(level="INFO")
    def reach_onair_aic(self, lua_cfg, logs_dirpath=None, timeout=180, check_edaemon_port=False, align_tac_values=True,
                        x2_setup_pass_regexp=".*"):
        """
        Run WTS application and start Core simulation. Wait until cells reach 'on air'. As a last step, try to setup X2AP interface
        with an option to check the result in AiC.
        :param lua_cfg: File path of .lua config file
        :param logs_dirpath: Directory for output logs
        :param timeout: Timeout for cells enabling, MIB and SIB1 reception
        :param check_edaemon_port: Default False, if True then function will search for port in lua_cfg
        :param align_tac_values: Default True, the function will align TAC values in .lua/.cfg file to scf
        :param x2_setup_pass_regexp: Default ".*", the function will set x2_setup_pass_regexp
        :param number_of_vdu: number of vdu
        :return:
        """
        number_of_vdu = ta5g_admin_operations().get_number_of_vdu()
        if not logs_dirpath:
            logs_dirpath = ta5g_interface_tools().get_robot_output_dir()
        ta5g_testline_management.ta5g_testline_management.start_default_simulated_SANSA_interfaces()
        self.start_wts_and_store_config_file_in_logs_dir_aic(lua_cfg=lua_cfg, logs_dirpath=logs_dirpath,
                                                             check_edaemon_port=check_edaemon_port,
                                                             align_tac_values=align_tac_values)
        ta5g_iphy.ta5g_iphy().check_radios_availability_aic(timeout=timeout, number_of_vdu=number_of_vdu)
        ta5g_admin_operations().check_if_f1_links_available_aic()
        self._ute_wtssim_instance.execute_egate_command(cmd='start version_check=off', timeout=10)
        self.ta5g_cell_operations.wait_for_all_cells_to_be_enabled_aic(timeout=timeout)
        self.wait_for_mib_reception_aic(timeout=timeout)
        self.wait_for_sib1_reception_aic(timeout=timeout)
        self._ute_wtssim_instance.execute_egate_command(cmd="enb_x2_link_up enb=1 target=2",
                                                        pass_regexp=x2_setup_pass_regexp,
                                                        timeout=5)

    @staticmethod
    def determine_details_of_mib_aic():
        number_of_cells = ta5g_cell_operations().get_number_of_cells_aic()
        mib_cells_dict = {2: [i for i in range(1, number_of_cells + 1)]}  # noqa: C416
        return mib_cells_dict

    def determine_details_of_sibs1_to_check_aic(self):
        number_of_cells = ta5g_cell_operations().get_number_of_cells_aic()
        sib1_for_gnb = self.check_if_sib1_will_be_transmitted_for_5g_cells_aic(number_of_cells)
        cells_dict = {2: [i for i in range(1, number_of_cells + 1) if sib1_for_gnb[i]]}
        return cells_dict

    @log_name(level="INFO")
    def wait_for_mib_reception_aic(self, timeout=180):
        mib_cells_dict = self.determine_details_of_mib_aic()
        self.wait_for_information_block_reception_for_given_cells(
            cells=mib_cells_dict, infoblocktype='MasterInformationBlock', timeout=timeout)

    @log_name(level="INFO")
    def wait_for_sib1_reception_aic(self, timeout=60):
        cells_dict = self.determine_details_of_sibs1_to_check_aic()
        if cells_dict == {}:
            logger.info("NSA configuration, SIB1 turned off on gNB, omitting wait for sib reception", also_console=True)
            return True
        self.wait_for_information_block_reception_for_given_cells(
            cells=cells_dict, infoblocktype='SystemInformationBlockType1', timeout=timeout)
